/*
 * THE INBOX IN KEYS AND VALUES (DBU-08). coachInbox decides what is waiting; this only words it.
 * Every sentence is a Strings key plus the values for its {tags}. Times are the coach's (Europe/Paris).
 * Which item is open: the one chosen, if it is still there. Otherwise, on a wide screen, the oldest
 * (so dealing with one brings up the next); on a narrow screen none, which shows the list.
 * A check-in answered (DBU-10) carries its answers with the answer's own copy of its questions.
 */
if (Inputs.items === undefined || Inputs.kinds === undefined) return;
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const kinds = (Inputs.kinds || []).map((k) => ({ value: get(k, 'value'), labelKey: get(k, 'labelKey'), bg: get(k, 'bg'), fg: get(k, 'fg') }));
const kindOf = (v) => kinds.find((k) => k.value === v) || { labelKey: '', bg: 'var(--muted)', fg: 'var(--muted-foreground)' };
const items = Array.isArray(Inputs.items) ? Inputs.items : [];
const narrow = Inputs.narrow === true;
const DAY = 86400000;
const now = Date.now();
const t = (iso) => { const n = Date.parse(iso || ''); return Number.isFinite(n) ? n : 0; };
const ZONE = 'Europe/Paris';
const date = (iso) => (t(iso) ? new Date(iso).toLocaleDateString('en-GB', { timeZone: ZONE, weekday: 'short', day: 'numeric', month: 'short' }) : '');
// Days are calendar days in the coach's zone: something from yesterday evening is "Yesterday", not "16 h ago".
const dayNo = (ms) => Date.parse(new Date(ms).toLocaleDateString('en-CA', { timeZone: ZONE }) + 'T00:00:00Z') / DAY;
const daysSince = (iso) => (t(iso) ? dayNo(now) - dayNo(t(iso)) : 0);
const quietDays = (i) => daysSince(new Date(Math.max(t(i.facts && i.facts.lastActiveAt), t(i.facts && i.facts.startedOn))).toISOString());
const overdueOf = (i) => (i.reasons || []).filter((r) => r && r.kind === 'overdue');
const inactive = (i) => (i.reasons || []).some((r) => r && r.kind === 'inactive');

const age = (iso) => {
  const ms = Math.max(0, now - t(iso));
  const days = daysSince(iso);
  if (days >= 2) return { ageKey: 'inbox.ageDays', ageN: String(days) };
  if (days === 1) return { ageKey: 'inbox.ageYesterday', ageN: '' };
  if (ms < 3600000) return { ageKey: 'inbox.ageMinutes', ageN: String(Math.max(1, Math.floor(ms / 60000))) };
  return { ageKey: 'inbox.ageHours', ageN: String(Math.floor(ms / 3600000)) };
};
const summary = (i) => {
  const v = { title: i.title || '', body: i.body || '', n: String(i.count || ''), days: '', first: i.first || '', version: String(i.version || '') };
  if (i.kind === 'review') return Object.assign(v, { summaryKey: i.version > 1 ? 'inbox.sumReviewAgain' : 'inbox.sumReview' });
  if (i.kind === 'checkin') return Object.assign(v, { summaryKey: 'inbox.sumCheckin' });
  if (i.kind === 'question') {
    if (!v.body) return Object.assign(v, { summaryKey: 'inbox.sumQuestionFiles' });
    return Object.assign(v, { summaryKey: i.count > 1 ? 'inbox.sumQuestions' : 'inbox.sumQuestion' });
  }
  if (inactive(i)) return Object.assign(v, { summaryKey: 'inbox.sumQuiet', days: String(quietDays(i)) });
  const o = overdueOf(i)[0] || {};
  return Object.assign(v, { summaryKey: 'inbox.sumOverdue', title: o.title || '', days: String(daysSince(o.dueAt)) });
};

const chosen = String(Inputs.selectedId || '');
const current = items.find((i) => i.id === chosen) || (!narrow && items.length ? items[0] : null);

Outputs.rows = items.map((i) => {
  const k = kindOf(i.kind);
  return Object.assign({ id: i.id, itemId: i.id, kindKey: k.labelKey, kindBg: k.bg, kindFg: k.fg, learner: i.learner, selected: !!current && current.id === i.id }, summary(i), age(i.since));
});
Outputs.hasItems = items.length > 0;
Outputs.none = items.length === 0;
Outputs.showList = items.length > 0 && (!narrow || !current);
Outputs.showDetail = !!current;
Outputs.showBack = narrow && !!current;

const c = current || {};
const k = kindOf(c.kind);
Outputs.curId = c.id || '';
Outputs.curLearnerId = c.learnerId || '';
Outputs.curLearner = c.learner || '';
Outputs.curFirst = c.first || '';
Outputs.curKindKey = k.labelKey;
Outputs.curKindBg = k.bg;
Outputs.curKindFg = k.fg;
Outputs.isReview = c.kind === 'review';
Outputs.isQuestion = c.kind === 'question';
Outputs.isQuiet = c.kind === 'quiet';
Outputs.isCheckin = c.kind === 'checkin';
Outputs.hasTitle = c.kind === 'review' || c.kind === 'checkin';
Outputs.curTitle = c.title || '';
Outputs.curStepId = c.kind === 'review' ? c.stepId || '' : '';
Outputs.curSubmissions = c.kind === 'review' ? c.submissions || [] : [];
Outputs.curMessageId = c.kind === 'question' ? c.messageId || '' : '';
Outputs.curFlagId = c.kind === 'quiet' ? c.flagId || '' : '';
Outputs.curResponseId = c.kind === 'checkin' ? c.responseId || '' : '';
Outputs.curQuestions = c.kind === 'checkin' && c.form && Array.isArray(c.form.questions) ? c.form.questions : [];
Outputs.curAnswers = c.kind === 'checkin' && c.answers ? c.answers : {};

// Gone quiet: the facts, one sentence each, and what the nudge says next.
const facts = [];
if (c.kind === 'quiet') {
  const f = c.facts || {};
  const fact = (key, v) => facts.push(Object.assign({ id: c.id + '-fact-' + facts.length, key, title: '', date: '', days: '', first: c.first || '' }, v));
  if (f.startedOn) fact('inbox.factStarted', { date: date(f.startedOn) });
  if (f.lastSeenAt) fact('inbox.factSeen', { date: date(f.lastSeenAt), days: String(daysSince(f.lastSeenAt)) });
  else fact('inbox.factNeverSeen', {});
  if (f.lastActiveAt && f.lastActiveAt !== f.lastSeenAt) fact('inbox.factActive', { date: date(f.lastActiveAt) });
  if (f.nextSession) fact('inbox.factSession', { date: date(f.nextSession) });
  else fact('inbox.factNoSession', {});
  overdueOf(c).forEach((o) => fact('inbox.factOverdue', { title: o.title || '', date: date(o.dueAt) }));
  if (c.nudgedAt) fact('inbox.factNudged', { date: date(c.nudgedAt) });
}
Outputs.curFacts = facts;
const firstOverdue = overdueOf(c)[0];
Outputs.curNextKey = firstOverdue ? 'inbox.nudgeNextOverdue' : 'inbox.nudgeNextPlan';
Outputs.curNextTitle = firstOverdue ? firstOverdue.title || '' : '';
Outputs.go();
